// NFE — name is self-referential:
const factorial = function fact(n) {
  return n <= 1 ? 1 : n * fact(n - 1); // 'fact' accessible here
};
factorial(5); // 120
// fact(5);   // ReferenceError — name not in outer scope

// Arrow — no arguments:
const fn = (...args) => args; // must use rest params instead

function compose(...fns) {
  return x => fns.reduceRight((acc, fn) => fn(acc), x);
}
const add1  = x => x + 1;
const double = x => x * 2;
const square = x => x * x;

const transform = compose(add1, double, square);
console.log(transform(3));

function* idGen() {
  let id = 1;
  while (true) {
    const reset = yield id++;
    if (reset) id = 1;
  }
}
const gen = idGen();
console.log(gen.next().value);    // 1
console.log(gen.next().value);    // 2
console.log(gen.next(true).value);// 1 (reset)
console.log(gen.next().value);    // 2

// Declaration — hoisted:
sayHi(); // works!
function sayHi() { console.log('hi'); }

// Expression — not hoisted:
// sayBye(); // TypeError
const sayBye = function() { console.log('bye'); };

// Arrow — concise, lexical this:
const double = x => x * 2;

// No arguments object in arrow:
const fn = () => arguments; // ReferenceError in strict mode

// map — transforms each element:
Array.prototype.myMap = function(fn) {
  const result = [];
  for (let i = 0; i < this.length; i++) {
    result.push(fn(this[i], i, this));
  }
  return result;
};

// filter — keeps elements matching predicate:
Array.prototype.myFilter = function(fn) {
  const result = [];
  for (let i = 0; i < this.length; i++) {
    if (fn(this[i], i, this)) result.push(this[i]);
  }
  return result;
};

// reduce — accumulates a single value:
Array.prototype.myReduce = function(fn, initial) {
  let acc = initial !== undefined ? initial : this[0];
  let start = initial !== undefined ? 0 : 1;
  for (let i = start; i < this.length; i++) {
    acc = fn(acc, this[i], i, this);
  }
  return acc;
};

[1,2,3].myMap(x => x * 2);         // [2,4,6]
[1,2,3,4].myFilter(x => x % 2===0); // [2,4]
[1,2,3,4].myReduce((a,b) => a+b);   // 10
